#[allow(clippy::too_many_arguments)]
fn coalesced_refresh_message(
    subs: usize,
    added: usize,
    updated: usize,
    removed: usize,
    failed: usize,
    conflicts: usize,
    in_use: usize,
) -> Option<(bool, String)> {
    if subs == 0 {
        return None;
    }
    let mut text = format!(
        "Background refresh: {subs} subscription(s): [+]Added {added} / [~]Updated {updated} / [-]Deleted {removed}"
    );
    if in_use > 0 {
        text.push_str(&format!(" / [=] Still in use {in_use}"));
    }
    if failed == 0 && conflicts == 0 {
        Some((false, text))
    } else {
        let mut full = format!("{text} · {failed} failed");
        if conflicts > 0 {
            full.push_str(&format!(" · {conflicts} conflict(s) — your edits kept"));
        }
        Some((true, full))
    }
}

