fn bulk_delete_confirm_description(count: usize, names: &[String]) -> String {
    const SHOWN: usize = 3;
    if names.is_empty() {
        return format!(
            "Delete {count} checked configuration(s)? Running endpoints stop first. This cannot be undone."
        );
    }
    let shown = names
        .iter()
        .take(SHOWN)
        .map(|name| format!("\"{name}\""))
        .collect::<Vec<_>>()
        .join(", ");
    let more = if names.len() > SHOWN {
        format!(" +{} more", names.len() - SHOWN)
    } else {
        String::new()
    };
    format!(
        "Delete {count} checked configuration(s) ({shown}{more})? Running endpoints stop first. This cannot be undone."
    )
}

fn bulk_delete_result_message(removed: &[String], failed: &[String]) -> String {
    const SHOWN: usize = 3;
    fn listed(names: &[String]) -> String {
        let shown = names
            .iter()
            .take(SHOWN)
            .map(|name| format!("\"{name}\""))
            .collect::<Vec<_>>()
            .join(", ");
        if names.len() > SHOWN {
            format!("{shown} +{} more", names.len() - SHOWN)
        } else {
            shown
        }
    }
    if failed.is_empty() {
        if removed.is_empty() {
            return "Deleted 0 configuration(s)".to_string();
        }
        return format!(
            "Deleted {} configuration(s): {}",
            removed.len(),
            listed(removed)
        );
    }
    if removed.is_empty() {
        return format!(
            "Delete failed for {} configuration(s): {}",
            failed.len(),
            listed(failed)
        );
    }
    format!(
        "Deleted {} · {} failed: {}",
        removed.len(),
        failed.len(),
        listed(failed)
    )
}

fn duplicate_name(base: &str, taken: &[String]) -> String {
    let first = format!("{base} copy");
    if !taken.iter().any(|name| name == &first) {
        return first;
    }
    let mut index = 2usize;
    loop {
        let candidate = format!("{first} {index}");
        if !taken.iter().any(|name| name == &candidate) {
            return candidate;
        }
        index += 1;
    }
}

