#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RowPhase {
    Stopped,
    Starting,
    Running,
    Failed,
}

impl RowPhase {
    fn of(is_running: bool, starting: bool, failed: bool) -> Self {
        if starting {
            Self::Starting
        } else if failed {
            Self::Failed
        } else if is_running {
            Self::Running
        } else {
            Self::Stopped
        }
    }

    fn start_label(self) -> &'static str {
        match self {
            Self::Starting => "Starting…",
            Self::Stopped | Self::Running | Self::Failed => "Start",
        }
    }
}

