const SEARCH_PLACEHOLDER: &str = "Search configurations";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RowColumns {
    upstream: bool,
    health: bool,
    group: bool,
    traffic: bool,
}

impl Default for RowColumns {
    fn default() -> Self {
        Self {
            upstream: true,
            health: true,
            group: false,
            traffic: false,
        }
    }
}

impl RowColumns {
    const ORDER: [&'static str; 4] = ["upstream", "health", "group", "traffic"];

    fn parse(raw: &str) -> Self {
        if raw.trim().is_empty() {
            return Self::default();
        }
        let mut columns = Self {
            upstream: false,
            health: false,
            group: false,
            traffic: false,
        };
        for token in raw.split(',').map(str::trim) {
            match token {
                "upstream" => columns.upstream = true,
                "health" => columns.health = true,
                "group" => columns.group = true,
                "traffic" => columns.traffic = true,
                _ => {}
            }
        }
        columns
    }

    fn display(self) -> String {
        if !self.upstream && !self.health && !self.group && !self.traffic {
            return "none".to_string();
        }
        let mut names = Vec::with_capacity(4);
        for name in Self::ORDER {
            let enabled = match name {
                "upstream" => self.upstream,
                "health" => self.health,
                "group" => self.group,
                _ => self.traffic,
            };
            if enabled {
                names.push(name);
            }
        }
        names.join(",")
    }
}

