fn panel_choices(prefix: &str, items: &[(&str, &str)]) -> Vec<PanelChoice> {
    items
        .iter()
        .map(|(value, title)| {
            let slug = if value.trim().is_empty() {
                "default".to_string()
            } else {
                value.to_string()
            };
            PanelChoice {
                id: format!("{prefix}-{slug}"),
                title: title.to_string(),
                display: title.to_string(),
                value: value.to_string(),
            }
        })
        .collect()
}

