    fn latency_sparkline(latencies: &[u64]) -> impl IntoElement {
        struct SparkPoint {
            x: String,
            y: f64,
        }
        let points: Vec<SparkPoint> = latencies
            .iter()
            .enumerate()
            .map(|(index, ms)| SparkPoint {
                x: index.to_string(),
                y: *ms as f64,
            })
            .collect();
        div().w(px(160.)).h(px(32.)).child(
            LineChart::new(points)
                .x(|point: &SparkPoint| point.x.clone())
                .y(|point: &SparkPoint| point.y)
                .x_axis(false)
                .grid(false),
        )
    }

    fn render_status_bar(&self, cx: &App) -> impl IntoElement {
        let libraries = self.libraries.read(cx);
        let delegate = libraries.delegate();
        let (total, enabled) = delegate.counts();
        let engine_text = self.engine.status_text();
        let health_text = self.health_status_text();

        let filter_text = delegate.active_filter_text();
        let ports: Vec<u16> = delegate
            .rows
            .iter()
            .filter(|row| self.engine.is_running(&row.id))
            .map(|row| row.port)
            .collect();
        let ports_text = serving_ports_text(&ports);

        let count_text = format!(
            "{} {} · {} enabled",
            total,
            if total == 1 {
                "configuration"
            } else {
                "configurations"
            },
            enabled
        );
        let mut left = div()
            .id("status-left")
            .test_support()
            .flex()
            .flex_row()
            .items_center()
            .gap_2()
            .min_w(px(210.))
            .child({
                let tip = count_text.clone();
                div()
                    .id("status-count")
                    .test_support()
                    .min_w(px(180.))
                    .truncate()
                    .tooltip(move |_, cx| cx.new(|_| Tooltip::new(tip.clone())).into())
                    .child(count_text)
            });

        if !filter_text.is_empty() {
            let tip = filter_text.clone();
            left = left.child(Separator::vertical()).child(
                div()
                    .id("status-filter")
                    .test_support()
                    .min_w_0()
                    .max_w(px(280.))
                    .truncate()
                    .tooltip(move |_, cx| cx.new(|_| Tooltip::new(tip.clone())).into())
                    .child(filter_text),
            );
        }
        let mut center = div()
            .id("status-center")
            .test_support()
            .flex()
            .flex_row()
            .items_center()
            .gap_2()
            .min_w(px(430.))
            .child({
                let tip = engine_text.clone();
                div()
                    .id("engine-status")
                    .test_support()
                    .min_w(px(140.))
                    .truncate()
                    .tooltip(move |_, cx| cx.new(|_| Tooltip::new(tip.clone())).into())
                    .child(engine_text)
            })
            .child(Separator::vertical())
            .child({
                let tip = health_text.clone();
                div()
                    .id("health-status")
                    .test_support()
                    .min_w(px(190.))
                    .truncate()
                    .tooltip(move |_, cx| cx.new(|_| Tooltip::new(tip.clone())).into())
                    .child(health_text)
            });

        if let Some(ports) = ports_text {
            center = center.child(Separator::vertical()).child({
                let tip = ports.clone();
                div()
                    .id("status-ports")
                    .test_support()
                    .min_w_0()
                    .max_w(px(200.))
                    .truncate()
                    .tooltip(move |_, cx| cx.new(|_| Tooltip::new(tip.clone())).into())
                    .child(ports)
            });
        }
        let mut right = div()
            .id("status-right")
            .test_support()
            .flex()
            .flex_row()
            .items_center()
            .gap_2()
            .min_w(px(150.));
        if let Some(totals) = summed_traffic_text(&self.store) {
            right = right.child(Separator::vertical()).child({
                let tip = totals.clone();
                div()
                    .id("traffic-status")
                    .test_support()
                    .min_w_0()
                    .max_w(px(200.))
                    .truncate()
                    .tooltip(move |_, cx| cx.new(|_| Tooltip::new(tip.clone())).into())
                    .child(totals)
            });
        }

        StatusBar::new().left(left).child(center).right(right)
    }

    fn render_search_count(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let (visible, total, query) = self
            .libraries
            .read(cx)
            .delegate()
            .delegate_counts_for_search();
        let has_query = !query.trim().is_empty();
        let clear_view = cx.entity();
        div()
            .id("search-count")
            .test_support()
            .flex()
            .flex_row()
            .items_center()
            .gap_2()
            .px_2()
            .py_1()
            .child(search_count_text(visible, total))
            .child(if has_query {
                Button::new("clear-search")
                    .small()
                    .label("Clear search")
                    .tooltip("Clear the search query (keeps facet filters and checked)")
                    .on_click(move |_, window, cx| {
                        clear_view.update(cx, |view, cx| {
                            view.clear_library_search(window, cx);
                        });
                    })
                    .into_any_element()
            } else {
                div()
                    .id("search-count-idle")
                    .test_support()
                    .into_any_element()
            })
            .into_any_element()
    }

    fn focus_library_search(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.search_input.focus_handle(cx).focus(window, cx);
    }

    fn sync_search_box(view: &Entity<Self>, text: &str, window: &mut Window, cx: &mut App) {
        view.update(cx, |view, cx| {
            view.search_input.update(cx, |input, cx| {
                input.set_value(text.to_string(), window, cx);
            });
        });
    }

    fn clear_library_search(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.search_input.update(cx, |input, cx| {
            input.set_value(String::new(), window, cx);
        });
        self.libraries.update(cx, |state, list_cx| {
            state.set_query("", window, list_cx);
        });
        cx.notify();
    }

    fn render_empty_ctas(&self, _cx: &mut Context<Self>) -> impl IntoElement {
        div().id("empty-ctas").test_support()
    }

    fn sync_facet_pickers(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        for menu in FacetMenu::ALL {
            let (choices, current) = menu.choices(self.libraries.read(cx).delegate());
            let picker = match menu {
                FacetMenu::Group => &mut self.facet_group,
                FacetMenu::Protocol => &mut self.facet_protocol,
                FacetMenu::Status => &mut self.facet_status,
            };
            Self::sync_facet_picker(picker, choices, current, window, cx);
        }
    }

    fn sync_facet_picker(
        picker: &mut FacetPicker,
        choices: Vec<FacetChoice>,
        current: Option<String>,
        window: &mut Window,
        cx: &mut Context<AppView>,
    ) {
        if picker.synced != choices {
            picker.synced = choices.clone();
            picker.state.update(cx, |state, cx| {
                state.set_items(FacetChoiceList(choices.clone()), window, cx);
                state.set_selected_value(&current, window, cx);
            });
            return;
        }
        let selected = picker.state.read(cx).selected_value().cloned().flatten();
        if selected != current {
            picker.state.update(cx, |state, cx| {
                state.set_selected_value(&current, window, cx);
            });
        }
    }

    fn render_facet_bar(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> impl IntoElement {
        self.sync_facet_pickers(window, cx);
        let has_facets = self.libraries.read(cx).delegate().facets_active();
        // T-19: the facet area carries the same per-group opt-in switch for
        // the focused group; has no group to protect by design.
        let facet_group_now = self.libraries.read(cx).delegate().facet_group.clone();
        let facet_auto_clear = facet_group_now
            .as_deref()
            .map(|group| self.store.auto_clear_enabled(group))
            .unwrap_or(false);
        let facet_auto_view = cx.entity();

        let (group_tip, protocol_tip, status_tip) = {
            let libraries = self.libraries.read(cx);
            let delegate = libraries.delegate();
            let (visible, total, _) = delegate.delegate_counts_for_search();
            (
                facet_tip_text(
                    "group",
                    &FacetMenu::Group.current_display(delegate),
                    visible,
                    total,
                ),
                facet_tip_text(
                    "protocol",
                    &FacetMenu::Protocol.current_display(delegate),
                    visible,
                    total,
                ),
                facet_tip_text(
                    "status",
                    &FacetMenu::Status.current_display(delegate),
                    visible,
                    total,
                ),
            )
        };
        div()
            .id("facet-bar")
            .test_support()
            .flex()
            .flex_row()
            .flex_wrap()
            .items_center()
            .gap_2()
            .px_2()
            .py_1()
            .border_b_1()
            .border_color(cx.theme().border)
            .child(
                div()
                    .id("library-search")
                    .test_support()
                    .flex_1()
                    .min_w(px(140.))
                    .child(
                        Input::new(&self.search_input)
                            .small()
                            .aria_label("Search configurations (Ctrl-F)"),
                    ),
            )
            .child(self.render_search_count(cx))
            .child(
                div()
                    .id("facet-group-tip")
                    .test_support()
                    .tooltip(move |_, cx| cx.new(|_| Tooltip::new(group_tip.clone())).into())
                    .child(
                        Select::new(&self.facet_group.state)
                            .id("facet-group")
                            .small()
                            .accessibility_label("Filter by group"),
                    ),
            )
            .child(
                div()
                    .id("facet-protocol-tip")
                    .test_support()
                    .tooltip(move |_, cx| cx.new(|_| Tooltip::new(protocol_tip.clone())).into())
                    .child(
                        Select::new(&self.facet_protocol.state)
                            .id("facet-protocol")
                            .small()
                            .accessibility_label("Filter by protocol"),
                    ),
            )
            .child(
                div()
                    .id("facet-status-tip")
                    .test_support()
                    .tooltip(move |_, cx| cx.new(|_| Tooltip::new(status_tip.clone())).into())
                    .child(
                        Select::new(&self.facet_status.state)
                            .id("facet-status")
                            .small()
                            .accessibility_label("Filter by status"),
                    ),
            )
            .child(
                Button::new("groups-dialog")
                    .small()
                    .label("Groups")
                    .tooltip("Rename or merge groups")
                    .on_click(cx.listener(|view, _, window, cx| {
                        view.open_groups_dialog(window, cx);
                    })),
            )
            .child(match facet_group_now {
                Some(group) => {
                    let slug = slugify_group_id(&group);
                    div()
                        .id(format!("facet-auto-clear-{slug}"))
                        .test_support()
                        .child(
                            Switch::new(format!("facet-auto-clear-switch-{slug}"))
                                .checked(facet_auto_clear)
                                .label("Auto-clear unavailable")
                                .tooltip(
                                    "Opt-in per group: after this group's URL test ends, its \
                                     unavailable rows are removed automatically. Running rows \
                                     and the row being edited are never removed; enabling asks \
                                     its own confirmation.",
                                )
                                .accessibility_label(format!(
                                    "Auto-clear unavailable rows in group \"{group}\" after group tests"
                                ))
                                .on_change({
                                    let facet_auto_view = facet_auto_view.clone();
                                    move |next: &bool, window, cx| {
                                        let view = facet_auto_view.clone();
                                        if *next {
                                            view.update(cx, |view, cx| {
                                                view.open_auto_clear_opt_in_confirm(
                                                    &group, false, window, cx,
                                                )
                                            });
                                        } else {
                                            view.update(cx, |view, cx| {
                                                view.commit_auto_clear_off(&group, window, cx)
                                            });
                                        }
                                    }
                                }),
                        )
                        .into_any_element()
                }
                None => div()
                    .id("facet-auto-clear-idle")
                    .test_support()
                    .into_any_element(),
            })
            .child(if has_facets {
                Button::new("clear-facets")
                    .small()
                    .label("Clear facet filters")
                    .tooltip("Clear group, protocol and status filters (keeps search and checked)")
                    .on_click(cx.listener(|view, _, window, cx| {
                        view.clear_facets(window, cx);
                    }))
                    .into_any_element()
            } else {
                div().id("facets-idle").test_support().into_any_element()
            })
            .into_any_element()
    }

    fn render_bulk_bar(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let label = self.libraries.read(cx).delegate().bulk_label();
        if label.is_empty() {
            return div().id("bulk-bar").test_support().into_any_element();
        }

        Self::motion_enter(
            div()
                .id("bulk-bar")
                .test_support()
                .flex()
                .flex_row()



                .flex_wrap()
                .items_center()
                .gap_2()
                .px_2()
                .py_1()
                .bg(cx.theme().group_box)
                .border_b_1()
                .border_color(cx.theme().border)
                .child(
                    div()
                        .id("bulk-label")
                        .test_support()
                        .tooltip(|_, cx| {
                            cx.new(|_| {
                                Tooltip::new(
                                    "Blue wash = selected (F5). Blue rim + number = checked (bulk).",
                                )
                            })
                            .into()
                        })
                        .child(label),
                )



                .child(
                    Button::new("bulk-select-visible")
                        .small()
                        .label("Check all visible")
                        .tooltip("Check every visible row")
                        .on_click(cx.listener(|view, _, window, cx| {
                            view.select_visible_checked(window, cx);
                        })),
                )
                .child(
                    Button::new("bulk-clear")
                        .small()
                        .label("Uncheck all")
                        .tooltip("Uncheck all (Esc)")
                        .on_click(cx.listener(|view, _, window, cx| {
                            view.clear_checked(window, cx);
                        })),
                )
                .child(Separator::vertical())
                .child(
                    Button::new("bulk-start")
                        .small()
                        .label("Start checked")
                        .tooltip("Start every checked endpoint")
                        .on_click(cx.listener(|view, _, window, cx| {
                            view.commit_bulk_start(window, cx);
                        })),
                )
                .child(
                    Button::new("bulk-stop")
                        .small()
                        .label("Stop checked")
                        .tooltip("Stop every checked endpoint")
                        .on_click(cx.listener(|view, _, window, cx| {
                            view.commit_bulk_stop(window, cx);
                        })),
                )
                .child(
                    Button::new("bulk-enable")
                        .small()
                        .label("Enable")
                        .tooltip("Enable every checked row")
                        .on_click(cx.listener(|view, _, window, cx| {
                            view.commit_bulk_enable(true, window, cx);
                        })),
                )
                .child(
                    Button::new("bulk-disable")
                        .small()
                        .label("Disable")
                        .tooltip("Disable every checked row")
                        .on_click(cx.listener(|view, _, window, cx| {
                            view.commit_bulk_enable(false, window, cx);
                        })),
                )
                .child(
                    Button::new("bulk-move")
                        .small()
                        .label("Move to group")
                        .tooltip("Move every checked row")
                        .on_click(cx.listener(|view, _, window, cx| {
                            view.open_bulk_move_dialog(window, cx);
                        })),
                )


                .child(Separator::vertical())
                .child(
                    Button::new("bulk-delete")
                        .danger()
                        .small()
                        .label("Delete")
                        .tooltip("Delete every checked row")
                        .on_click(cx.listener(|view, _, window, cx| {
                            view.open_bulk_delete_confirm(window, cx);
                        })),
                )
                .into_any_element(),
            "bulk-bar-enter",
            cx,
        )
        .into_any_element()
    }

    fn clear_facets(&mut self, _window: &mut Window, cx: &mut Context<Self>) {
        self.libraries.update(cx, |state, list_cx| {
            state.delegate_mut().clear_facets();
            list_cx.notify();
        });
        cx.notify();
    }

    fn clear_checked(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.libraries.update(cx, |state, list_cx| {
            state.delegate_mut().clear_checked();
            list_cx.notify();
        });

        window.focus(&self.focus, cx);
        cx.notify();
    }

    fn clear_checked_unless_dialog(&mut self, window: &mut Window, cx: &mut Context<Self>) -> bool {
        if overlay_open(window, cx) {
            return false;
        }
        self.clear_checked(window, cx);
        true
    }

    fn select_visible_checked(&mut self, _window: &mut Window, cx: &mut Context<Self>) {
        self.libraries.update(cx, |state, list_cx| {
            let ids: Vec<String> = state
                .delegate()
                .visible_rows()
                .iter()
                .map(|row| row.id.clone())
                .collect();
            let delegate = state.delegate_mut();
            for id in ids {
                if !delegate.checked.contains(&id) {
                    delegate.toggle_checked(&id);
                }
            }
            list_cx.notify();
        });
        cx.notify();
    }

    fn commit_bulk_enable(&mut self, enabled: bool, window: &mut Window, cx: &mut Context<Self>) {
        let ids: Vec<String> = self
            .libraries
            .read(cx)
            .delegate()
            .checked_rows()
            .iter()
            .map(|row| row.id.clone())
            .collect();
        if ids.is_empty() {
            window.push_notification(Notification::info(no_selection_message()), cx);
            return;
        }
        let mut ok = 0usize;
        let mut failed = 0usize;
        for id in &ids {
            match self.store.set_enabled(id, enabled) {
                Ok(_) => ok += 1,
                Err(_) => failed += 1,
            }
        }
        self.reload(window, cx);
        let verb = if enabled { "Enabled" } else { "Disabled" };
        if failed == 0 {
            window.push_notification(
                Notification::success(format!("{verb} {ok} configuration(s)")),
                cx,
            );
        } else {
            window.push_notification(
                Notification::warning(format!("{verb} {ok}, {failed} failed")),
                cx,
            );
        }
    }

    fn commit_bulk_start(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let rows = self.libraries.read(cx).delegate().checked_rows();
        if rows.is_empty() {
            window.push_notification(Notification::info(no_selection_message()), cx);
            return;
        }
        if self.start_in_flight {
            window.push_notification(Notification::info(start_busy_message()), cx);
            return;
        }
        let lan: Vec<(String, String)> = rows
            .iter()
            .filter(|row| requires_lan_confirm(&row.bind_ip))
            .map(|row| (row.name.clone(), row.bind_ip.clone()))
            .collect();
        if !lan.is_empty() {
            let view = cx.entity();
            let ids: Vec<String> = rows.iter().map(|row| row.id.clone()).collect();
            let description = lan_confirm_description(&lan);
            window.open_alert_dialog(cx, move |alert, _, _| {
                let view = view.clone();
                let ids = ids.clone();
                let description = description.clone();
                alert
                    .confirm()
                    .button_props(
                        DialogButtonProps::default()
                            .show_cancel(true)
                            .ok_text("Start"),
                    )
                    .title(LAN_CONFIRM_TITLE)
                    .description(description)
                    .on_ok(move |_, window, cx| {
                        let ids = ids.clone();
                        view.update(cx, |view, cx| view.commit_bulk_start_ids(&ids, window, cx));
                        true
                    })
            });
            return;
        }
        let ids: Vec<String> = rows.iter().map(|row| row.id.clone()).collect();
        if cfg!(test) {
            self.commit_bulk_start_ids(&ids, window, cx);
        } else {
            self.spawn_commit_bulk_start_ids(ids, window, cx);
        }
    }

    fn commit_bulk_start_ids(
        &mut self,
        ids: &[String],
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.start_in_flight {
            window.push_notification(Notification::info(start_busy_message()), cx);
            return;
        }
        self.start_in_flight = true;
        if let Err(reason) = self.sync_presets_to_engine() {
            self.start_in_flight = false;
            window.push_notification(Notification::error(format!("Cannot start: {reason}")), cx);
            return;
        }
        let mut started = 0usize;
        let mut failed: Vec<String> = Vec::new();
        let mut skipped_dirty: Vec<String> = Vec::new();
        let mut unreadable: Vec<String> = Vec::new();
        let mut flag_failed: Vec<String> = Vec::new();
        for id in ids {
            if self.libraries.read(cx).delegate().endpoint_is_dirty(id, cx) {
                if let Ok(Some(config)) = self.store.get(id) {
                    skipped_dirty.push(config.name.clone());
                }
                continue;
            }
            let config = match self.store.get(id) {
                Ok(Some(config)) => config,
                Ok(None) => continue,
                Err(_) => {
                    unreadable.push(id.clone());
                    continue;
                }
            };
            if let Some(warning) = lan_exposure_warning(&config.name, &config.bind_ip) {
                window.push_notification(Notification::warning(warning), cx);
            }
            match self.engine.start_one_confirmed(&config) {
                Ok(()) => {
                    started += 1;
                    if self.store.set_enabled(id, true).is_err() {
                        flag_failed.push(config.name.clone());
                    }
                }
                Err(error) => {
                    failed.push(format!(
                        "{}: {}",
                        config.name,
                        redact_secrets(&error.to_string())
                    ));
                }
            }
        }
        self.start_in_flight = false;
        self.reload(window, cx);
        if !skipped_dirty.is_empty() {
            window.push_notification(
                Notification::info(skipped_dirty_message(&skipped_dirty)),
                cx,
            );
        }
        if !unreadable.is_empty() {
            window.push_notification(
                Notification::warning(bulk_start_unreadable_message(&unreadable)),
                cx,
            );
        }
        if !flag_failed.is_empty() {
            window.push_notification(
                Notification::warning(bulk_start_enable_flag_failed_message(&flag_failed)),
                cx,
            );
        }
        if failed.is_empty() {
            window.push_notification(
                Notification::success(format!("Started {started} configuration(s)")),
                cx,
            );
        } else {
            window.push_notification(
                Notification::error(format!(
                    "Started {started}, {} failed: {}",
                    failed.len(),
                    failed.join("; ")
                )),
                cx,
            );
        }
    }

    fn spawn_commit_start_selected(&mut self, id: String, window: &Window, cx: &mut Context<Self>) {
        let handle = window.window_handle();
        let view = cx.entity().clone();
        cx.spawn(async move |_, cx| {
            cx.background_executor()
                .timer(Duration::from_millis(1))
                .await;
            let _ = handle.update(cx, |_, window, cx| {
                view.update(cx, |view, cx| {
                    view.commit_start_selected(&id, window, cx);
                });
            });
        })
        .detach();
    }

