    #[gpui_kit::test]
    fn t02_topbar_has_no_mode_controls(cx: &mut TestAppContext) {
        cx.update(gpui_kit::init);
        cx.update(|cx| cx.set_reduce_motion(true));
        let store = Store::open_in_memory().expect("in-memory store opens");
        let (_view, cx) = mount_view(store, cx);
        paint_frame(cx);
        let mut names: Vec<String> = Vec::new();

        for id in [
            "program-menu",
            "settings-menu",
            "groups-menu",
            "routing-menu",
            "tools-menu",
            "global-start-stop",
        ] {
            names.push(cx.update(|window, _| {
                window
                    .try_find(id.to_string())
                    .unwrap_or_else(|| panic!("{id} renders"))
                    .label()
                    .map(str::to_string)
                    .unwrap_or_default()
            }));
        }

        for (trigger, items) in [
            (
                "program-menu",
                &[
                    "menu-add-config",
                    "menu-import-config",
                    "import-clipboard",
                    "import-files",
                    "export-library",
                    "about-dialog",
                ][..],
            ),
            ("settings-menu", &["settings-dialog"][..]),
            (
                "groups-menu",
                &[
                    "subscriptions",
                    "menu-groups-dialog",
                    "prune-duplicates",
                    "prune-unavailable",
                    "prune-invalid",
                    "prune-clear-tests",
                ][..],
            ),
            (
                "routing-menu",
                &["routing-presets", "routing-open-settings"][..],
            ),
            (
                "tools-menu",
                &[
                    "start-selected",
                    "stop-selected",
                    "test-selected",
                    "menu-logs",
                    "engine-start-all",
                    "engine-stop-all",
                    "health-test-all",
                    "test-group",
                    "speedtest-selected",
                    "speedtest-group",
                    "speedtest-mode",
                    "out-ip-selected",
                    "out-ip-group",
                    "resolve-domain-group",
                    "stop-testing",
                    "show-security",
                    "sort-type-security",
                    "open-palette",
                ][..],
            ),
        ] {
            cx.update(|window, cx| {
                window.click(trigger, cx);
            });
            cx.run_until_parked();
            paint_frame(cx);
            cx.run_until_parked();
            paint_frame(cx);
            for &id in items {
                names.push(cx.update(|window, _| {
                    window
                        .try_find(id.to_string())
                        .unwrap_or_else(|| panic!("{id} renders in the {trigger} menu"))
                        .label()
                        .map(str::to_string)
                        .unwrap_or_default()
                }));
            }
            cx.update(|window, cx| {
                use gpui_kit::Keystroke;
                let escape = Keystroke::parse("escape").expect("test keystroke parses");
                window.dispatch_keystroke(escape, cx);
            });
            cx.run_until_parked();
            paint_frame(cx);
        }
        for name in &names {
            let lowered = name.to_lowercase();
            for banned in [
                "tun",
                "system proxy",
                "system dns",
                "hijack",
                "warp",
                "elevation",
            ] {
                assert!(
                    !lowered.contains(banned),
                    "no mode control on the top bar, got {name:?}"
                );
            }
        }
        assert!(!names.is_empty(), "scanned the whole bar");
    }

