        cx.update(|window, cx| {
            window.scroll(
                "config-detail-body",
                gpui_kit::ScrollDelta::Pixels(point(px(0.), px(-100_000.))),
                cx,
            );
        });
        cx.run_until_parked();
        paint_frame(cx);
        cx.run_until_parked();
        paint_frame(cx);
